fn eval_geomerics_sh_pair(sh: vec4<f32>, n: vec3<f32>, refl: vec3<f32>, need_refl: bool) -> vec2<f32> {
    let r0 = max(sh.x, 1e-5);
    let l1 = sh.yzw;
    let l1_len = length(l1);
    let r = clamp(l1_len / r0, 0.0, 1.0);
    let l1_dir = l1 * (1.0 / max(l1_len, 1e-5));
    let p = 1.0 + 2.0 * r;
    let a = (1.0 - r) / (1.0 + r);
    let c1 = (1.0 - a) * (p + 1.0);
    let qn = clamp(0.5 * (1.0 + dot(n, l1_dir)), 0.0, 1.0);
    let dn = max(r0 * (a + c1 * pow(qn, p)), 0.0);
    var dr = dn;
    if need_refl {
