    let gg = eval_geomerics_sh_pair(textureSampleLevel(gi_sh_g, gi_sampler, uvw, 0.0), n, refl, need_refl);
    let gb = eval_geomerics_sh_pair(textureSampleLevel(gi_sh_b, gi_sampler, uvw, 0.0), n, refl, need_refl);
    return GiPair(vec3<f32>(gr.x, gg.x, gb.x) * 1.55, vec3<f32>(gr.y, gg.y, gb.y));
