fn eval_lantern_glow(world_pos: vec3<f32>, n: vec3<f32>, albedo: vec3<f32>, metallic: f32) -> vec3<f32> {
    if world_pos.x < -21.0 || world_pos.x > 13.5 || world_pos.y > 11.5 || abs(world_pos.z) > 12.0 {
