fn build_tangent_frame(e1: vec3<f32>, e2: vec3<f32>, du1: vec2<f32>, du2: vec2<f32>, n: vec3<f32>) -> vec4<f32> {
    let det = du1.x * du2.y - du1.y * du2.x;
    if abs(det) <= 1e-8 {
