    }
    let inv_det = 1.0 / det;
    let t_raw = (e1 * du2.y - e2 * du1.y) * inv_det;
    let b_raw = (e2 * du1.x - e1 * du2.x) * inv_det;
    let t_ortho = t_raw - n * dot(n, t_raw);
    let t_l2 = dot(t_ortho, t_ortho);
