            nm_xy = textureSampleGrad(mat_normal, pbr_sampler, uv_interp, li, grad_x, grad_y).rg;
            orm_gb = textureSampleGrad(mat_orm, pbr_sampler, uv_interp, li, grad_x, grad_y).gb;
